const menu = document.querySelector('.menu-toggle');
const navigation = document.querySelector('#navigation');
menu.addEventListener('click', () => {const open = menu.getAttribute('aria-expanded') !== 'true';menu.setAttribute('aria-expanded', String(open));navigation.classList.toggle('open', open);});
navigation.querySelectorAll('a').forEach(link => link.addEventListener('click', () => {menu.setAttribute('aria-expanded', 'false');navigation.classList.remove('open');}));
const paths = {
 college: {kicker:'THE COLLEGE PATH',title:'Find the place where\nyou can go further.',description:'Explore colleges, fields of study, and the community and legacy of HBCUs.',topics:['Discover colleges and fields of study','Understand applications and financial aid'],question:'“What would I want from my college experience?”',words:'GO\nFURTHER',foot:'CURIOSITY TODAY.\nPOSSIBILITY TOMORROW.'},
 trades: {kicker:'THE SKILLED TRADES PATH',title:'Build skills.\nBuild your future.',description:'Explore trade schools, apprenticeships, and hands-on careers.',topics:['Explore skilled trades and technical careers','Compare training and apprenticeship options'],question:'“What do I enjoy making, fixing, or figuring out?”',words:'BUILD\nWHAT’S NEXT',foot:'HANDS-ON SKILLS.\nREAL-WORLD POSSIBILITY.'},
 business: {kicker:'THE ENTREPRENEURSHIP PATH',title:'See a possibility.\nStart something.',description:'Turn your interests and the problems you notice into a business idea.',topics:['Find ideas connected to your strengths','Learn the basics of planning and money'],question:'“What problem would I love to solve?”',words:'MAKE\nYOUR MARK',foot:'A SMALL IDEA.\nA NEW BEGINNING.'}
};
const tabs=[...document.querySelectorAll('[data-path]')];
function selectPath(tab,focus=false){const data=paths[tab.dataset.path];tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;});document.querySelector('#path-panel').setAttribute('aria-labelledby',tab.id);document.querySelector('#path-kicker').textContent=data.kicker;const heading=document.querySelector('#path-title');heading.replaceChildren(...data.title.split('\n').flatMap((line,i)=>i?[document.createElement('br'),document.createTextNode(line)]:[document.createTextNode(line)]));document.querySelector('#path-description').textContent=data.description;document.querySelector('#path-topics').replaceChildren(...data.topics.map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));document.querySelector('#path-question').textContent=data.question;const word=document.querySelector('.path-word');word.replaceChildren(...data.words.split('\n').flatMap((line,i)=>i?[document.createElement('br'),document.createTextNode(line)]:[document.createTextNode(line)]));const arrow=document.createElement('span');arrow.textContent='↗';word.append(arrow);word.style.fontSize=tab.dataset.path==='college'?'':'clamp(36px, 4vw, 56px)';const foot=document.querySelector('.path-art-bottom');foot.replaceChildren(...data.foot.split('\n').flatMap((line,i)=>i?[document.createElement('br'),document.createTextNode(line)]:[document.createTextNode(line)]));if(focus)tab.focus();}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectPath(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();selectPath(tabs[next],true);});});
const audienceInfo={student:{title:'Your future. Your questions.',copy:'You don’t need a finished plan to start exploring. Here are a few conversation starters for students and families:',items:['What would I like to do better or feel more confident about in high school?','Which path interests me: college, skilled trades, entrepreneurship—or am I still exploring?','What would I like to learn from a mentor?']},mentor:{title:'Your experience can matter.',copy:'Interested in supporting young men at Edgewood? Start by thinking about the experiences and perspective you could bring:',items:['What lessons from high school, an HBCU, or my career would I share?','How can I listen to students and help them explore their own goals?','What would I like to ask about the program’s mentor expectations and time commitment?']}};
const dialog=document.querySelector('#interest-dialog');let activeAudience='student';let previousFocus;
document.querySelectorAll('[data-audience]').forEach(button=>button.addEventListener('click',()=>{activeAudience=button.dataset.audience;previousFocus=button;const data=audienceInfo[activeAudience];document.querySelector('#dialog-title').textContent=data.title;document.querySelector('#dialog-copy').textContent=data.copy;document.querySelector('#dialog-list').replaceChildren(...data.items.map(text=>{const li=document.createElement('li');li.textContent=text;return li;}));document.querySelector('.download-status').textContent='';dialog.showModal();}));
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>previousFocus?.focus());
document.querySelector('#download-guide').addEventListener('click',()=>{const data=audienceInfo[activeAudience];const text=['EDGEWOOD MALE MENTORING PROGRAM',data.title,'',data.copy,'',...data.items.map((item,i)=>`${i+1}. ${item}\n\nMy thoughts: \n`),'Program contact and enrollment details will be posted on the website when available.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`edgewood-${activeAudience}-conversation-starters.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('.download-status').textContent='Your conversation starters have been prepared for download.';});
document.querySelector('#year').textContent=new Date().getFullYear();
